layers.vertex:
attribute vec3 aO; attribute float aT, aK; attribute vec4 aD; uniform float uTime; varying vec2 vP; varying float vU, vK, vR;
    void main(){ float u = uTime - aT; if (u < 0. || u > 1.00){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK; vP = position.xy;
      if (aK > 2.5 && aK < 3.5){                              // Weave: a resource mote flies back to the caster on a curved path
        float k = clamp((u - aD.w)/.45, 0., 1.); if (u < aD.w || k >= 1.){ gl_Position = vec4(2.,2.,2.,1.); return; }
        float e = k*k*(3. - 2.*k); vec3 A = aO + vec3(0., 1.2, 0.), B = aD.xyz;
        vec3 side = normalize(cross(B - A, vec3(0., 1., 0.)))*sin(aD.w*37.)*.8;
        vec3 P = mix(A, B, e) + (side + vec3(0., .9, 0.))*sin(3.14159*e);
        vec4 mv = viewMatrix*vec4(P, 1.); float S = .09; mv.xy += position.xy*S; vU = k; gl_Position = projectionMatrix*mv; return; }
      if (aK > 3.5){                                          // charge: a stored shard converges from the waist orbit to the hand (reverse ease-in)
        float k = clamp(u/0.40, 0., 1.); if (k >= 1.){ gl_Position = vec4(2.,2.,2.,1.); return; }
        vec3 P = mix(aD.xyz, aO, k*k*k);
        vec4 mv = viewMatrix*vec4(P, 1.); mv.xy += position.xy*vec2(.07, .13); vU = k; gl_Position = projectionMatrix*mv; return; }
      vR = aD.x;
      if (aK < .5){ float S = aD.x + .25; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.); }
      else if (aK < 1.5){ vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.25, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.32; mv.xy += position.xy*vec2(.26, .3); gl_Position = projectionMatrix*mv; }
      else { vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.15, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.3; float S = .75*aD.x; mv.xy += position.xy*S; vP = position.xy*.75; gl_Position = projectionMatrix*mv; }
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vK, vR; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float h1(float n){ return fract(sin(n*91.7)*43758.5); }
    void main(){
      float lum = 0., hot = 0., t = vU/1.00;
      if (vK > 3.5){                                          // charge shard: small crystal, brightens as it arrives
        vec2 q = vP; float d = abs(q.x) + abs(q.y)*.55 - .55;
        vec3 o = (uOrange*(lcore(d, .07)*.8 + .18*smoothstep(.05, -.1, d)) + mix(uGold, vec3(1.), .4)*lcore(q.x, .05)*smoothstep(0., -.2, d)*.6)*(.8 + .8*vU);
        o *= smoothstep(1., .8, length(q));
        if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); return;
      }
      if (vK < .5){
        // AoE circle: after the hit stop, a thin ring opens fast to the radius (ease-out), holds a moment, fades; soft inner wash
        float r = length(vP), u2 = vU - 0.06; if (u2 < 0.) discard;
        float R = vR*(.25 + .75*(1. - pow(1. - clamp(u2/.18, 0., 1.), 3.))), f = (u2 < .033 ? 1.6 : 1.)*(1. - smoothstep(.3, .6, u2));
        lum += (exp(-pow(abs(r - R)/.02, 2.4)) + exp(-pow((r - R)/.12, 2.))*.15 + smoothstep(R, R*.2, r)*.06)*f; hot += lcore(r - R, .006)*f*.5;
        lum *= smoothstep(vR + .25, vR + .12, r); hot *= smoothstep(vR + .25, vR + .12, r);
      } else if (vK < 1.5){
        // kind 1 (unused here): inherited Burn sigil from Combust, not spawned by Arcane Burst
        float x = vP.x, y = vP.y*.5 + .5, t = clamp((vU - .2)/.6, 0., 1.);
        vec2 q = vec2(x*2.2, (y - .55)*4.6); float r = length(q);
        float flame = smoothstep(.55, .45, length(vec2(q.x*(1.3 + q.y*.5), q.y + .2)))*smoothstep(-.9, -.4, q.y)*(1. - smoothstep(.55, 1.1, q.y + .1*sin(vU*30.)));
        float edge = flame*(1. - smoothstep(.3, .45, length(vec2(q.x*(1.3 + q.y*.5), q.y + .2))));
        float f = step(.2, vU)*(vU < .233 ? 1.8 : 1.)*(1. - smoothstep(.55, 1., t));
        lum += (flame - edge*.7)*f*1.1; hot = edge*f*.2;
        lum *= smoothstep(1., .75, abs(x)); hot *= smoothstep(1., .75, abs(x));
      } else {
        if (vK > 2.5){ float r = length(vP); float m = exp(-r*r*8.)*(1. - vU)*1.6;       // Weave mote
          vec3 o = uGold*m + vec3(1., .95, .8)*exp(-r*r*40.)*(1. - vU);
          if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); return; }
        // chest pop after the hit stop: the sphere bursts into a bright disc and one clean ring, no debris
        float r = length(vP), u2 = vU - 0.06; if (u2 < 0.) discard;
        float t2 = clamp(u2/.3, 0., 1.), R = .1 + .35*(1. - pow(1. - t2, 3.));
        float body = exp(-r*r*(30. + 60.*t2))*(u2 < .033 ? 2. : 1.3*(1. - t2));
        float rim = exp(-pow((r - R)/.025, 2.))*(1. - t2);
        lum += body + rim; hot = body*.6 + exp(-r*r*150.)*(1. - t2)*.8;
        lum *= smoothstep(.75, .62, r); hot *= smoothstep(.75, .62, r);
      }
      vec3 o = uOrange*lum + mix(uGold, vec3(1.), .5)*hot;
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.);
    }
